1	//! Self-contained landscape HTML — snapshot JSON embedded in a single file, no
2	//! network fetch, no build step. The page stages `residual add …` commands for
3	//! the operator to copy; it never mutates the ledger.
4	
5	use anyhow::Result;
6	
7	use crate::view::snapshot::{
8	    DefenseSection, ForceKind, LandscapeSnapshot, SnapshotAttractor, SnapshotComponent,
9	    SnapshotForce, SnapshotMetaForce, SnapshotResidue,
10	};
11	
12	/// The single-file page shell. Rendering substitutes [`SNAPSHOT_PLACEHOLDER`].
13	pub const TEMPLATE: &str = include_str!("template.html");
14	
15	/// Token in [`TEMPLATE`] replaced by the serialized snapshot.
16	pub const SNAPSHOT_PLACEHOLDER: &str = "{{SNAPSHOT_JSON}}";
17	
18	/// Element id of the `<script type="application/json">` block holding the snapshot.
19	pub const SNAPSHOT_ELEMENT_ID: &str = "residual-snapshot";
20	
21	const FORCE_LIST_PLACEHOLDER: &str = "{{FORCE_LIST}}";
22	const MATRIX_PLACEHOLDER: &str = "{{MATRIX}}";
23	const DEFENSE_FORMS_PLACEHOLDER: &str = "{{DEFENSE_FORMS}}";
24	
25	/// Render the full landscape page for a snapshot.
26	pub fn render_landscape_html(snapshot: &LandscapeSnapshot) -> Result<String> {
27	    let json = escape_script_json(&snapshot.to_json()?);
28	    let force_list = render_force_list(snapshot);
29	    let matrix = render_matrix(snapshot);
30	    let defense_forms = match &snapshot.defense {
31	        Some(defense) => render_defense_forms(defense),
32	        None => String::new(),
33	    };
34	
35	    let html = TEMPLATE
36	        .replace(SNAPSHOT_PLACEHOLDER, &json)
37	        .replace(FORCE_LIST_PLACEHOLDER, &force_list)
38	        .replace(MATRIX_PLACEHOLDER, &matrix)
39	        .replace(DEFENSE_FORMS_PLACEHOLDER, &defense_forms);
40	    Ok(html)
41	}
42	
43	/// Extract the embedded snapshot JSON from rendered HTML (round-trip helper).
44	pub fn extract_snapshot_json(html: &str) -> Option<&str> {
45	    let open = r#"<script id="residual-snapshot" type="application/json">"#;
46	    let start = html.find(open)? + open.len();
47	    let end = html[start..].find("</script>")? + start;
48	    Some(&html[start..end])
49	}
50	
51	/// Prevent ledger text from closing the embedding `<script>` block.
52	fn escape_script_json(json: &str) -> String {
53	    json.replace('<', r"\u003c")
54	}
55	
56	fn esc(value: &str) -> String {
57	    value
58	        .replace('&', "&amp;")
59	        .replace('<', "&lt;")
60	        .replace('>', "&gt;")
61	        .replace('"', "&quot;")
62	}
63	
64	fn force_kind_attr(kind: ForceKind) -> &'static str {
65	    match kind {
66	        ForceKind::Stressor => "stressor",
67	        ForceKind::Purpose => "purpose",
68	    }
69	}
70	
71	fn render_force_list(snapshot: &LandscapeSnapshot) -> String {
72	    let mut out = String::new();
73	
74	    let mut attractor_ids: Vec<String> = snapshot.attractors.iter().map(|a| a.id.clone()).collect();
75	    for force in snapshot.stressors.iter().chain(snapshot.purposes.iter()) {
76	        if !attractor_ids.iter().any(|id| id == &force.attractor_id) {
77	            attractor_ids.push(force.attractor_id.clone());
78	        }
79	    }
80	
81	    for attractor_id in &attractor_ids {
82	        let label = snapshot
83	            .attractors
84	            .iter()
85	            .find(|a| &a.id == attractor_id)
86	            .map(|a| a.name.as_str())
87	            .unwrap_or(attractor_id.as_str());
88	        out.push_str(&format!(
89	            r#"<div class="attractor-group" data-attractor-group="{}">"#,
90	            esc(attractor_id)
91	        ));
92	        out.push_str(&format!("<h3>{} · {}</h3>", esc(attractor_id), esc(label)));
93	
94	        for force in snapshot
95	            .stressors
96	            .iter()
97	            .chain(snapshot.purposes.iter())
98	            .filter(|f| &f.attractor_id == attractor_id)
99	        {
100	            out.push_str(&render_force_row(force, &snapshot.components, &snapshot.residues));
101	        }
102	        out.push_str("</div>");
103	    }
104	
105	    if !snapshot.components.is_empty() {
106	        out.push_str(r#"<div class="component-chips">"#);
107	        for component in &snapshot.components {
108	            out.push_str(&render_component_chip(component));
109	        }
110	        out.push_str("</div>");
111	    }
112	
113	    if let Some(defense) = &snapshot.defense {
114	        out.push_str(&render_defense_records(defense));
115	    }
116	
117	    out
118	}
119	
120	fn architecture_sets_for_force(
121	    force_id: &str,
122	    components: &[SnapshotComponent],
123	    residues: &[SnapshotResidue],
124	) -> String {
125	    let mut sets: Vec<&str> = residues
126	        .iter()
127	        .filter(|r| r.force_id == force_id && r.coupled)
128	        .filter_map(|r| {
129	            components
130	                .iter()
131	                .find(|c| c.name == r.component_id)
132	                .map(|c| c.architecture_set.as_str())
133	        })
134	        .collect();
135	    sets.sort_unstable();
136	    sets.dedup();
137	    sets.join(" ")
138	}
139	
140	fn render_force_row(
141	    force: &SnapshotForce,
142	    components: &[SnapshotComponent],
143	    residues: &[SnapshotResidue],
144	) -> String {
145	    let kind = force_kind_attr(force.kind);
146	    let arch = architecture_sets_for_force(&force.id, components, residues);
147	    let search = format!(
148	        "{} {} {} {} {}",
149	        force.id, force.shortname, kind, force.attractor_id, arch
150	    );
151	    format!(
152	        r#"<div class="force-row" data-force-id="{id}" data-force-kind="{kind}" data-architecture-set="{arch}" data-search="{search}"><span class="force-id">{id}</span><span>{short} <span class="force-kind">{kind}</span></span><span></span><span>{desc}</span></div>"#,
153	        id = esc(&force.id),
154	        kind = kind,
155	        arch = esc(&arch),
156	        search = esc(&search),
157	        short = esc(&force.shortname),
158	        desc = esc(&force.description),
159	    )
160	}
161	
162	fn render_component_chip(component: &SnapshotComponent) -> String {
163	    let search = format!(
164	        "{} {} {}",
165	        component.name, component.architecture_set, component.status
166	    );
167	    format!(
168	        r#"<div class="component-chip" data-component="{name}" data-architecture-set="{arch}" data-search="{search}"><span class="force-id">{name}</span><span>{arch} · {status}</span></div>"#,
169	        name = esc(&component.name),
170	        arch = esc(&component.architecture_set),
171	        status = esc(&component.status),
172	        search = esc(&search),
173	    )
174	}
