176	fn render_matrix(snapshot: &LandscapeSnapshot) -> String {
177	    let forces: Vec<&SnapshotForce> = snapshot
178	        .stressors
179	        .iter()
180	        .chain(snapshot.purposes.iter())
181	        .collect();
182	    let mut out = String::from(r#"<table class="matrix"><thead><tr><th>force</th>"#);
183	    for component in &snapshot.components {
184	        out.push_str(&format!(
185	            r#"<th data-component="{}">{}</th>"#,
186	            esc(&component.name),
187	            esc(&component.name)
188	        ));
189	    }
190	    out.push_str("</tr></thead><tbody>");
191	
192	    for force in forces {
193	        out.push_str("<tr>");
194	        out.push_str(&format!(
195	            r#"<th data-force-id="{}">{}</th>"#,
196	            esc(&force.id),
197	            esc(&force.id)
198	        ));
199	        for component in &snapshot.components {
200	            let residue = snapshot.residues.iter().find(|r| {
201	                r.force_id == force.id && r.component_id == component.name
202	            });
203	            let coupled = residue.map(|r| r.coupled).unwrap_or(false);
204	            let coupled_attr = if coupled { "1" } else { "0" };
205	            let body = if coupled { "1" } else { "" };
206	            out.push_str(&format!(
207	                r#"<td data-residue-cell data-force-id="{force}" data-component="{comp}" data-coupled="{coupled}">{body}</td>"#,
208	                force = esc(&force.id),
209	                comp = esc(&component.name),
210	                coupled = coupled_attr,
211	                body = body,
212	            ));
213	        }
214	        out.push_str("</tr>");
215	    }
216	    out.push_str("</tbody></table>");
217	    out
218	}
