220	fn render_defense_records(defense: &DefenseSection) -> String {
221	    let mut out = String::from(r#"<div class="defense-records"><h3>Defense</h3><ul>"#);
222	    for force in defense
223	        .meta_stressors
224	        .iter()
225	        .chain(defense.meta_purposes.iter())
226	    {
227	        out.push_str(&render_meta_force_item(force));
228	    }
229	    for attractor in &defense.meta_attractors {
230	        out.push_str(&render_meta_attractor_item(attractor));
231	    }
232	    for name in &defense.personas {
233	        out.push_str(&format!("<li>persona · {}</li>", esc(name)));
234	    }
235	    for name in &defense.strategies {
236	        out.push_str(&format!("<li>strategy · {}</li>", esc(name)));
237	    }
238	    for name in &defense.progress {
239	        out.push_str(&format!("<li>progress · {}</li>", esc(name)));
240	    }
241	    for name in &defense.pitches {
242	        out.push_str(&format!("<li>pitch · {}</li>", esc(name)));
243	    }
244	    out.push_str("</ul></div>");
245	    out
246	}
