354	mod tests {
355	    use super::*;
356	    use crate::view::snapshot::{ForceKind, LandscapeSnapshot, RecordSource, SnapshotForce};
357	    use crate::view::testing::{fixture_defense_snapshot, fixture_main_snapshot};
358	
359	    fn html(include_defense: bool) -> String {
360	        let snap = if include_defense {
361	            fixture_defense_snapshot()
362	        } else {
363	            fixture_main_snapshot()
364	        };
365	        render_landscape_html(&snap).expect("landscape html renders")
