416	    /// The filter input is not just markup — real JS must wire it to the
417	    /// data-search/data-force-kind/data-architecture-set attributes so typing
418	    /// actually hides/shows rows (the markup-only test above doesn't cover this).
419	    #[test]
420	    fn template_wires_working_filter_js_to_force_rows() {
421	        assert!(
422	            TEMPLATE.contains(r#"querySelector("[data-force-filter]")"#),
423	            "template must look up the filter input by its data-force-filter hook"
424	        );
425	        assert!(
426	            TEMPLATE.contains(r#".addEventListener("input""#),
427	            "filter input must react live as the operator types"
428	        );
429	        assert!(
430	            TEMPLATE.contains(r#"querySelectorAll(".force-row, .component-chip")"#),
431	            "filter must target force rows and component chips"
432	        );
433	        assert!(
434	            TEMPLATE.contains(r#"getAttribute("data-search")"#),
435	            "filter must read the per-row data-search haystack (which embeds kind and architecture_set)"
436	        );
437	        assert!(
438	            TEMPLATE.contains("row.hidden ="),
439	            "filter must actually toggle row visibility, not just compute a match"
440	        );
441	        assert!(
442	            TEMPLATE.contains(r#"querySelectorAll("[data-attractor-group]")"#)
443	                && TEMPLATE.contains("group.hidden ="),
444	            "filter must also collapse attractor groups left empty by the filter"
445	        );
446	    }
