272	    <script>
273	      function shellQuote(value) {
274	        const s = String(value == null ? "" : value);
275	        if (s.indexOf("\n") !== -1 || s.indexOf("\r") !== -1) {
276	          let escaped = "";
277	          for (const ch of s) {
278	            if (ch === "\\") escaped += "\\\\";
279	            else if (ch === "'") escaped += "\\'";
280	            else if (ch === "\n") escaped += "\\n";
281	            else if (ch === "\r") escaped += "\\r";
282	            else if (ch === "\t") escaped += "\\t";
283	            else escaped += ch;
284	          }
285	          return "$'" + escaped + "'";
286	        }
287	        return "'" + s.replace(/'/g, "'\\''") + "'";
288	      }
289	
290	      function pushFlag(parts, flag, value) {
291	        parts.push(flag + " " + shellQuote(value));
292	      }
293	
294	      function pushOptionalFlag(parts, flag, value) {
295	        if (value != null && String(value) !== "") pushFlag(parts, flag, value);
296	      }
297	
298	      function buildAddCommand(target, fields) {
299	        const f = fields || {};
300	        const parts = ["residual add " + target];
301	        switch (target) {
302	          case "stressor":
303	          case "purpose":
304	          case "meta-purpose":
305	            pushFlag(parts, "--description", f.description || "");
306	            pushFlag(parts, "--attractor-id", f.attractor_id || "");
307	            pushFlag(parts, "--naive-change", f.naive_change || "");
308	            pushOptionalFlag(parts, "--shortname", f.shortname || "");
309	            pushOptionalFlag(parts, "--outcomes", f.outcomes || "");
310	            break;
311	          case "attractor":
312	          case "meta-attractor":
313	            pushFlag(parts, "--name", f.name || "");
314	            pushFlag(parts, "--description", f.description || "");
315	            pushFlag(parts, "--positive-state", f.positive_state || "");
316	            pushFlag(parts, "--negative-state", f.negative_state || "");
317	            break;
318	          case "component":
319	            pushFlag(parts, "--name", f.name || "");
320	            pushFlag(parts, "--description", f.description || "");
321	            pushFlag(parts, "--status", f.status || "");
322	            pushFlag(parts, "--architecture-set", f.architecture_set || "");
323	            break;
324	          case "meta-stressor":
325	            pushFlag(parts, "--description", f.description || "");
326	            pushOptionalFlag(parts, "--shortname", f.shortname || "");
327	            break;
328	          case "defense-persona":
329	          case "defense-strategy":
330	          case "defense-progress":
331	          case "defense-pitch":
332	            pushFlag(parts, "--name", f.name || "");
333	            pushFlag(parts, "--body", f.body || "");
334	            break;
335	          default:
336	            throw new Error("unknown add target: " + target);
337	        }
338	        return parts.join(" ");
339	      }
340	
341	      function formFields(form) {
342	        const data = {};
343	        for (const el of form.querySelectorAll("input, textarea, select")) {
344	          if (!el.name) continue;
345	          data[el.name] = el.value;
346	        }
347	        return data;
348	      }
349	
350	      function appendStaged(command) {
351	        const box = document.getElementById("staged-commands");
352	        box.value = box.value ? box.value + "\n" + command : command;
353	      }
354	
355	      document.querySelectorAll("form[data-command-generator]").forEach((form) => {
356	        form.addEventListener("submit", (ev) => {
357	          ev.preventDefault();
358	          const target = form.getAttribute("data-command-generator");
359	          appendStaged(buildAddCommand(target, formFields(form)));
360	        });
361	      });
362	
363	      const filterInput = document.querySelector("[data-force-filter]");
364	      if (filterInput) {
365	        filterInput.addEventListener("input", () => {
366	          const q = filterInput.value.trim().toLowerCase();
367	          document.querySelectorAll(".force-row, .component-chip").forEach((row) => {
368	            const hay = (row.getAttribute("data-search") || row.textContent || "").toLowerCase();
369	            row.hidden = q !== "" && hay.indexOf(q) === -1;
370	          });
371	          document.querySelectorAll("[data-attractor-group]").forEach((group) => {
372	            const visible = group.querySelectorAll(".force-row:not([hidden])").length > 0;
373	            group.hidden = q !== "" && !visible;
374	          });
375	        });
376	      }
377	
378	      const copyBtn = document.getElementById("copy-staged");
379	      if (copyBtn) {
380	        copyBtn.addEventListener("click", async () => {
381	          const box = document.getElementById("staged-commands");
382	          if (navigator.clipboard && navigator.clipboard.writeText) {
383	            await navigator.clipboard.writeText(box.value);
384	          } else {
385	            box.select();
386	            document.execCommand("copy");
387	          }
388	        });
389	      }
390	      const clearBtn = document.getElementById("clear-staged");
391	      if (clearBtn) {
392	        clearBtn.addEventListener("click", () => {
393	          document.getElementById("staged-commands").value = "";
394	        });
395	      }
396	    </script>
397	  </body>
