131	    pub fn hyperliminal_pairs(&self) -> Vec<(String, String)> {
132	        let num_cols = self.components.len();
133	        let mut pairs = Vec::new();
134	        for i in 0..num_cols {
135	            for j in (i + 1)..num_cols {
136	                let shared = self
137	                    .cells
138	                    .iter()
139	                    .filter(|row| row[i] == 1 && row[j] == 1)
140	                    .count();
141	                if shared >= 2 {
142	                    pairs.push((self.components[i].clone(), self.components[j].clone()));
143	                }
144	            }
145	        }
