149	    pub fn fusion_candidates(&self) -> Vec<(String, String)> {
150	        let num_cols = self.components.len();
151	        let mut pairs = Vec::new();
152	        for i in 0..num_cols {
153	            for j in (i + 1)..num_cols {
154	                let identical = self.cells.iter().all(|row| row[i] == row[j]);
155	                if identical {
156	                    pairs.push((self.components[i].clone(), self.components[j].clone()));
157	                }
158	            }
159	        }
160	        pairs
161	    }
