383	    <script>
384	      function shellQuote(value) {
385	        const s = String(value == null ? "" : value);
386	        if (s.indexOf("\n") !== -1 || s.indexOf("\r") !== -1) {
387	          let escaped = "";
388	          for (const ch of s) {
389	            if (ch === "\\") escaped += "\\\\";
390	            else if (ch === "'") escaped += "\\'";
391	            else if (ch === "\n") escaped += "\\n";
392	            else if (ch === "\r") escaped += "\\r";
393	            else if (ch === "\t") escaped += "\\t";
394	            else escaped += ch;
395	          }
396	          return "$'" + escaped + "'";
397	        }
398	        return "'" + s.replace(/'/g, "'\\''") + "'";
399	      }
400	
401	      function pushFlag(parts, flag, value) {
402	        parts.push(flag + " " + shellQuote(value));
403	      }
404	
405	      function pushOptionalFlag(parts, flag, value) {
406	        if (value != null && String(value) !== "") pushFlag(parts, flag, value);
407	      }
408	
409	      function buildAddCommand(target, fields) {
410	        const f = fields || {};
411	        const parts = ["residual add " + target];
412	        switch (target) {
413	          case "stressor":
414	          case "purpose":
415	          case "meta-purpose":
416	            pushFlag(parts, "--description", f.description || "");
417	            pushFlag(parts, "--attractor-id", f.attractor_id || "");
418	            pushFlag(parts, "--naive-change", f.naive_change || "");
419	            pushOptionalFlag(parts, "--shortname", f.shortname || "");
420	            pushOptionalFlag(parts, "--outcomes", f.outcomes || "");
421	            break;
422	          case "attractor":
423	          case "meta-attractor":
424	            pushFlag(parts, "--name", f.name || "");
425	            pushFlag(parts, "--description", f.description || "");
426	            pushFlag(parts, "--positive-state", f.positive_state || "");
427	            pushFlag(parts, "--negative-state", f.negative_state || "");
428	            break;
429	          case "component":
430	            pushFlag(parts, "--name", f.name || "");
431	            pushFlag(parts, "--description", f.description || "");
432	            pushFlag(parts, "--status", f.status || "");
433	            pushFlag(parts, "--architecture-set", f.architecture_set || "");
434	            break;
435	          case "meta-stressor":
436	            pushFlag(parts, "--description", f.description || "");
437	            pushOptionalFlag(parts, "--shortname", f.shortname || "");
438	            break;
439	          case "defense-persona":
440	          case "defense-strategy":
441	          case "defense-progress":
442	          case "defense-pitch":
443	            pushFlag(parts, "--name", f.name || "");
444	            pushFlag(parts, "--body", f.body || "");
445	            break;
446	          default:
447	            throw new Error("unknown add target: " + target);
448	        }
449	        return parts.join(" ");
450	      }
451	
452	      function formFields(form) {
453	        const data = {};
454	        for (const el of form.querySelectorAll("input, textarea, select")) {
455	          if (!el.name) continue;
456	          data[el.name] = el.value;
457	        }
458	        return data;
459	      }
460	
461	      function appendStaged(command) {
462	        const box = document.getElementById("staged-commands");
463	        box.value = box.value ? box.value + "\n" + command : command;
464	      }
465	
466	      document.querySelectorAll("form[data-command-generator]").forEach((form) => {
467	        form.addEventListener("submit", (ev) => {
468	          ev.preventDefault();
469	          const target = form.getAttribute("data-command-generator");
470	          appendStaged(buildAddCommand(target, formFields(form)));
471	        });
472	      });
473	
474	      const filterInput = document.querySelector("[data-force-filter]");
475	      if (filterInput) {
476	        filterInput.addEventListener("input", () => {
477	          const q = filterInput.value.trim().toLowerCase();
478	          document.querySelectorAll("table.matrix tbody tr.force-row").forEach((row) => {
479	            const hay = (row.getAttribute("data-search") || row.textContent || "").toLowerCase();
480	            row.hidden = q !== "" && hay.indexOf(q) === -1;
481	          });
482	        });
483	      }
484	
485	      document.querySelectorAll("[data-accordion-toggle]").forEach((btn) => {
486	        btn.addEventListener("click", () => {
487	          const detail = btn.nextElementSibling;
488	          if (!detail) return;
489	          const expanded = btn.getAttribute("aria-expanded") === "true";
490	          btn.setAttribute("aria-expanded", String(!expanded));
491	          detail.hidden = expanded;
492	        });
493	      });
494	
495	      function sortMatrixBy(key, dir) {
496	        const table = document.querySelector("table.matrix");
497	        const tbody = table && table.querySelector("tbody");
498	        if (!tbody) return;
499	        const rows = Array.from(tbody.querySelectorAll("tr.force-row"));
500	        const mult = dir === "desc" ? -1 : 1;
501	        rows.sort((ra, rb) => {
502	          if (key === "force") {
503	            const va = ra.getAttribute("data-force-id") || "";
504	            const vb = rb.getAttribute("data-force-id") || "";
505	            return va.localeCompare(vb) * mult;
506	          }
507	          if (key === "total") {
508	            const va = Number(ra.getAttribute("data-row-total") || 0);
509	            const vb = Number(rb.getAttribute("data-row-total") || 0);
510	            return (va - vb) * mult;
511	          }
512	          if (key.indexOf("component:") === 0) {
513	            const comp = key.slice("component:".length);
514	            const ca = ra.querySelector('td[data-component="' + CSS.escape(comp) + '"]');
515	            const cb = rb.querySelector('td[data-component="' + CSS.escape(comp) + '"]');
516	            const va = ca && ca.getAttribute("data-coupled") === "1" ? 1 : 0;
517	            const vb = cb && cb.getAttribute("data-coupled") === "1" ? 1 : 0;
518	            return (va - vb) * mult;
519	          }
520	          return 0;
521	        });
522	        rows.forEach((row) => tbody.appendChild(row));
523	      }
524	
525	      document.querySelectorAll("table.matrix thead th[data-sort-key]").forEach((th) => {
526	        const activate = () => {
527	          const key = th.getAttribute("data-sort-key");
528	          const current = th.classList.contains("sort-asc")
529	            ? "asc"
530	            : th.classList.contains("sort-desc")
531	              ? "desc"
532	              : null;
533	          const next = current === "asc" ? "desc" : "asc";
534	          document.querySelectorAll("table.matrix thead th[data-sort-key]").forEach((other) => {
535	            other.classList.remove("sort-asc", "sort-desc");
536	          });
537	          th.classList.add(next === "asc" ? "sort-asc" : "sort-desc");
538	          sortMatrixBy(key, next);
539	        };
540	        th.addEventListener("click", activate);
541	        th.addEventListener("keydown", (ev) => {
542	          if (ev.key === "Enter" || ev.key === " ") {
543	            ev.preventDefault();
544	            activate();
545	          }
546	        });
547	      });
