549	      function computeMatrixCandidates() {
550	        const table = document.querySelector("table.matrix");
551	        const fusion = new Set();
552	        const fission = new Set();
553	        if (!table) return { fusion, fission };
554	
555	        const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map((th) =>
556	          th.getAttribute("data-component")
557	        );
558	        const vectors = {};
559	        componentNames.forEach((name) => {
560	          vectors[name] = {};
561	        });
562	        table.querySelectorAll("tbody td[data-residue-cell]").forEach((td) => {
563	          const comp = td.getAttribute("data-component");
564	          const force = td.getAttribute("data-force-id");
565	          if (vectors[comp]) vectors[comp][force] = td.getAttribute("data-coupled") === "1";
566	        });
567	        for (let i = 0; i < componentNames.length; i++) {
568	          for (let j = i + 1; j < componentNames.length; j++) {
569	            const a = vectors[componentNames[i]];
570	            const b = vectors[componentNames[j]];
571	            const forceIds = Object.keys(a);
572	            const identical = forceIds.length > 0 && forceIds.every((fid) => a[fid] === b[fid]);
573	            if (identical) {
574	              fusion.add(componentNames[i]);
575	              fusion.add(componentNames[j]);
576	            }
577	          }
578	        }
579	
580	        const thresholdInput = document.querySelector("[data-threshold-input]");
581	        const threshold = thresholdInput ? Number(thresholdInput.value) : 1;
582	        table.querySelectorAll("tfoot td[data-col-total]").forEach((td) => {
583	          const total = Number(td.getAttribute("data-col-total"));
584	          if (total > threshold) fission.add(td.getAttribute("data-component"));
585	        });
586	
587	        return { fusion, fission };
588	      }
589	
590	      function applyFusionFissionHighlighting() {
591	        const table = document.querySelector("table.matrix");
592	        if (!table) return;
593	        const { fusion, fission } = computeMatrixCandidates();
594	        const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map((th) =>
595	          th.getAttribute("data-component")
596	        );
597	        const onlyToggle = document.querySelector("[data-fusion-fission-filter]");
598	        const only = !!(onlyToggle && onlyToggle.checked);
599	
600	        componentNames.forEach((name) => {
601	          const isFusion = fusion.has(name);
602	          const isFission = fission.has(name);
603	          const show = !only || isFusion || isFission;
604	          table.querySelectorAll('[data-component="' + CSS.escape(name) + '"]').forEach((el) => {
605	            el.setAttribute("data-fusion", isFusion ? "1" : "0");
606	            el.setAttribute("data-fission", isFission ? "1" : "0");
607	            el.hidden = !show;
608	          });
609	        });
610	      }
611	
612	      const thresholdInput = document.querySelector("[data-threshold-input]");
613	      const thresholdOutput = document.querySelector("[data-threshold-value]");
614	      const fusionFissionToggle = document.querySelector("[data-fusion-fission-filter]");
615	
616	      function initThreshold() {
617	        if (!thresholdInput) return;
618	        const numForces = document.querySelectorAll("table.matrix tbody tr.force-row").length;
619	        const max = Math.max(1, numForces);
620	        const def = Math.max(1, Math.floor(numForces / 2));
621	        thresholdInput.min = "1";
622	        thresholdInput.max = String(max);
623	        thresholdInput.value = String(def);
624	        if (thresholdOutput) thresholdOutput.textContent = String(def);
625	      }
626	      initThreshold();
627	      applyFusionFissionHighlighting();
628	
629	      if (thresholdInput) {
630	        thresholdInput.addEventListener("input", () => {
631	          if (thresholdOutput) thresholdOutput.textContent = thresholdInput.value;
632	          applyFusionFissionHighlighting();
633	        });
634	      }
635	      if (fusionFissionToggle) {
636	        fusionFissionToggle.addEventListener("change", applyFusionFissionHighlighting);
637	      }
638	
639	      const copyBtn = document.getElementById("copy-staged");
640	      if (copyBtn) {
641	        copyBtn.addEventListener("click", async () => {
642	          const box = document.getElementById("staged-commands");
643	          if (navigator.clipboard && navigator.clipboard.writeText) {
644	            await navigator.clipboard.writeText(box.value);
645	          } else {
646	            box.select();
647	            document.execCommand("copy");
648	          }
649	        });
650	      }
651	      const clearBtn = document.getElementById("clear-staged");
652	      if (clearBtn) {
653	        clearBtn.addEventListener("click", () => {
654	          document.getElementById("staged-commands").value = "";
655	        });
656	      }
657	    </script>
658	  </body>
659	</html>
